import ast
from pathlib import Path
for name in ['client.py','provider.py','tests/test_client.py']:
 p=Path(name); data=p.read_bytes(); tree=ast.parse(data[:16384].decode())
 matches=[]
 for node in ast.walk(tree):
  if isinstance(node,(ast.AsyncFunctionDef,ast.Await,ast.AsyncFor,ast.AsyncWith)): matches.append(type(node).__name__)
  if isinstance(node,ast.Import) and any(a.name.split('.')[0] in {'asyncio','anyio','trio'} for a in node.names): matches.append('async import')
  if isinstance(node,ast.ImportFrom) and (node.module or '').split('.')[0] in {'asyncio','anyio','trio'}: matches.append('async import')
 print(f'Predicate: Python async conditional; path={name}; inspected={min(len(data),16384)} bytes; complete={len(data)<=16384}; matches={matches}')
PY"

